INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Schweigen hier ein guter Ansatz?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation ist zentral"}, {"text": "Ja", "correct": false, "because": "Austausch gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Wert priorisiere ich für klare Lösungen?', 3, '[{"text": "Einfachheit", "correct": true, "because": "Komplexität vermeiden"}, {"text": "Kommunikation", "correct": false, "because": "Austausch zählt"}, {"text": "Feedback", "correct": false, "because": "Rückmeldung später"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien helfen mir im Team?', 5, '[{"text": "Kommunikation", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Feedback", "correct": true, "because": "Verbesserung durch Rückmeldung"}, {"text": "Isolation", "correct": false, "because": "Widerspricht Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einfachheit bedeutet weniger Code. b) Feedback ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Werten?', 4, '[{"text": "Kommunikation", "correct": false, "because": "Grundprinzip"}, {"text": "Einfachheit", "correct": false, "because": "Kern der Entwicklung"}, {"text": "Komplexe Planung", "correct": true, "because": "Einfachheit bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Feedback hier selten gesucht wird?', 2, '[{"text": "Nein", "correct": true, "because": "Feedback ist zentral"}, {"text": "Ja", "correct": false, "because": "Regelmäßig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Wert nutze ich für enge Zusammenarbeit?', 3, '[{"text": "Kommunikation", "correct": true, "because": "Austausch fördern"}, {"text": "Einfachheit", "correct": false, "because": "Lösungen klar"}, {"text": "Feedback", "correct": false, "because": "Rückmeldung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundsätze fördern gute Ergebnisse?', 5, '[{"text": "Einfachheit", "correct": true, "because": "Weniger Fehler"}, {"text": "Feedback", "correct": true, "because": "Schnelle Anpassung"}, {"text": "Langfristige Pläne", "correct": false, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Kommunikation ist Schlüssel. b) Komplexität wird bevorzugt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einfachheit zählt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Kommunikation", "correct": false, "because": "Teamarbeit fördern"}, {"text": "Feedback", "correct": false, "because": "Verbesserung sichern"}, {"text": "Überkomplexität", "correct": true, "because": "Einfachheit bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Einfachheit hier zweitrangig?', 2, '[{"text": "Nein", "correct": true, "because": "Kernprinzip"}, {"text": "Ja", "correct": false, "because": "Komplexität vermeiden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte unterstützen schnelle Anpassung?', 4, '[{"text": "Feedback", "correct": true, "because": "Rückmeldung nutzen"}, {"text": "Kommunikation", "correct": true, "because": "Abstimmung ermöglichen"}, {"text": "Strikte Regeln", "correct": false, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier niemand redet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation essenziell"}, {"text": "Ja", "correct": false, "because": "Austausch gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem neuen Feature?', 3, '[{"text": "Einfachheit", "correct": true, "because": "Klare Lösung zuerst"}, {"text": "Komplexe Designs", "correct": false, "because": "Einfachheit zählt"}, {"text": "Keine Rückmeldung", "correct": false, "because": "Feedback nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback kommt schnell. b) Kommunikation ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stärken haben diese Werte?', 5, '[{"text": "Teamzusammenhalt", "correct": true, "because": "Kommunikation fördert"}, {"text": "Schnelle Verbesserung", "correct": true, "because": "Feedback nutzen"}, {"text": "Komplexe Strukturen", "correct": false, "because": "Einfachheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Einfachheit", "correct": false, "because": "Kernprinzip"}, {"text": "Feedback", "correct": false, "because": "Verbesserung fördern"}, {"text": "Stille Arbeit", "correct": true, "because": "Kommunikation zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Komplexität hier ein Ziel?', 3, '[{"text": "Nein", "correct": true, "because": "Einfachheit bevorzugt"}, {"text": "Ja", "correct": false, "because": "Komplexität vermeiden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Feedback hier ignoriert wird?', 2, '[{"text": "Nein", "correct": true, "because": "Feedback ist Kernwert"}, {"text": "Ja", "correct": false, "because": "Regelmäßig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Wert wähle ich für besseren Teamfluss?', 4, '[{"text": "Kommunikation", "correct": true, "because": "Abstimmung fördern"}, {"text": "Komplexität", "correct": false, "because": "Einfachheit zählt"}, {"text": "Einzelarbeit", "correct": false, "because": "Zusammenarbeit nötig"}]');
